    "templates.chatting.name": "雑談 (Just Chatting)",
    "templates.chatting.description": "持続ノイズを抑え、コンプで声を聴き取りやすく整える基本セットです。",
    "templates.chatting.slot0.label": "ノイズゲート",
    "templates.chatting.slot0.notes": "PCファンなどの持続ノイズを、喋っていないときに抑えます。閾値（Threshold）を調整して、無音時だけ効くようにします。",
    "templates.chatting.slot1.label": "コンプレッサー",
    "templates.chatting.slot1.notes": "声の大小の差を縮めて、聞き取りやすくします。Ratioを4:1、Gain Reductionが-3dB〜-6dB動く程度にします。",
    "templates.chatting.slot2.label": "リミッター",
    "templates.chatting.slot2.notes": "大きな声のピークを抑えるための調整例です。チェーンの最後に置き、Ceilingを-1.0dB程度に設定します。",
    "templates.singing.name": "歌枠 (Singing)",
    "templates.singing.description": "歌枠向けに、EQ・コンプ・リバーブ・リミッターを並べる構成例です。",
    "templates.singing.slot0.label": "イコライザー (EQ)",
    "templates.singing.slot0.notes": "100Hz以下をカットし、2kHz〜4kHzを少し持ち上げると抜けが良くなります。",
    "templates.singing.slot1.label": "コンプレッサー",
    "templates.singing.slot1.notes": "歌の抑揚を整えます。雑談より少し強めにかけるのが一般的です。",
    "templates.singing.slot2.label": "リバーブ",
    "templates.singing.slot2.notes": "空間の広がりを作ります。Send量（Mix）は控えめに、10%〜20%から始めましょう。",
    "templates.singing.slot3.label": "リミッター",
    "templates.singing.slot3.notes": "ピークを抑えるために、Ceilingと入力レベルを調整します。音割れを必ず防げるものではありません。",
    "templates.ASMR.name": "ASMR",
    "templates.ASMR.description": "ASMR向けにコンプとリミッターを並べる構成例です。音量制限や聴覚保護を保証するものではありません。",
    "templates.ASMR.slot0.label": "コンプレッサー (弱め)",
    "templates.ASMR.slot0.notes": "小さな音を持ち上げるために使います。Releaseは長めに設定します。",
    "templates.ASMR.slot1.label": "リミッター (保護)",
    "templates.ASMR.slot1.notes": "Ceilingと入力レベルを確認し、小さい再生音量から試してください。機器の音量や耳の安全を保証するものではありません。",
