    "guide.copy.103": "CABLE Input（VB-Audio 仮想ケーブル）",
    "guide.copy.104": "通話相手の声がループする危険性",
    "guide.copy.105": "ハードウェアのループバック機能を使ってDiscord通話をすると、",
    "guide.copy.106": "「相手の声」が自分のマイク音声に乗って相手に跳ね返る（エコー）",
    "guide.copy.107": "リスクが高いです。",
    "guide.copy.108": "対策: Discordの「出力デバイス」をループバックに含まれない経路（例: PCのヘッドホン端子など）にするか、ミキサー側で調整が必要です。",
    "guide.copy.109": "設定が難しい場合は、あえて「機材を使用していない」手順（VB-CABLE）を使うことをお勧めします。",
    "guide.copy.110": "自分の声を聞くには？",
    "guide.copy.111": "CABLE Input（VB-Audio 仮想ケーブル）を使うと自分の声が消えます。「PCのサウンド設定」で「このデバイスを聴く」をONにすることもできますが、遅延が発生するため推奨しません。",
    "guide.copy.112": "2. Discordの設定 (入力デバイス)",
    "guide.copy.113": "Discordのマイクとして、加工後の音声を選びます。",
    "guide.copy.114": "音声設定",
    "guide.copy.115": "入力デバイス",
    "guide.copy.116": "ループバック / 配信用ストリーム (お使いの機器)",
    "guide.copy.117": "CABLE Output（VB-Audio 仮想ケーブル）",
    "guide.copy.118": "出力デバイス",
    "guide.copy.119": "既定 / ヘッドホン",
    "guide.copy.120": "※ 重要: ここで設定した「入力デバイス」と同じ機材を「出力デバイス」に選ぶと、エコーが発生しやすくなります。",
    "guide.copy.121": "3. 音声処理を比較して調整する",
    "guide.copy.122": "Auralyn と受け側アプリの処理が重なると、声が欠けたり音量が変わったりする場合があります。",
    "guide.copy.123": "一つずつON・OFFを比較してください",
    "guide.copy.124": "ノイズ抑制 (Krisp / Standard)",
    "guide.copy.125": "→ 有無を比較",
    "guide.copy.126": "エコー除去",
    "guide.copy.127": "→ 有無を比較",
    "guide.copy.128": "音量調節の自動化",
    "guide.copy.129": "→ 有無を比較",
    "guide.copy.130": "ヘッドホン使用時はエコー除去の有無を比較できます。スピーカー使用時は、相手の声がマイクへ戻らないか確認し、必要なエコー除去を残してください。",
    "guide.copy.131": "入力感度",
    "guide.copy.132": "声が途切れる場合は自動検出の有無と感度を比較し、息や環境音だけで反応しない範囲に調整してください。",
    "guide.copy.133": "手順の案内のみです。受け側への音声到達は未確認です。受け側のメーターや試聴で確認してください。",
    "guide.copy.134": "接続診断を開く",
