    "guide.copy.141": "案内を閉じる",
    "guide.copy.142": "OBSで声と伴奏の取り込み元を確認し、デスクトップ音声・別マイクとの二重取り込みを確認しました",
    "guide.copy.143": "対象のミュート・音声モニタリングを確認しました（モニター音の再取り込みにも注意）",
    "guide.copy.144": "録音トラック・保存先・含まれる音を確認し、配信・通話に試験音が流れない状態にしました",
    "guide.copy.145": "OBSの最終ミックスを確認する（手動）",
    "guide.copy.146": "声単体のボイスチェックと、テスト音がOBSに届くかの接続診断だけでは、伴奏と声の音量バランスや最終録画は確認できません。",
    "guide.copy.147": "1. OBSで対象を確認する",
    "guide.copy.148": "OBSへの取り込み方",
    "guide.copy.149": "声と伴奏は別のソースです",
    "guide.copy.150": "声と伴奏は同じソースに混ざっています",
    "guide.copy.151": "混合済みのソース名",
    "guide.copy.152": "マイクのソース名",
    "guide.copy.153": "伴奏のソース名",
    "guide.copy.154": "機材のループバックなどで混合済みなら、OBSでは1つのソースとして確認できます。声と伴奏の個別音量は混ぜる前のミキサーや再生アプリで調整します。混合済みの取り込みと、同じ音を別の経路から重ねて取り込む「二重取り込み」は別です。",
    "guide.copy.155": "名前は手動メモです。接続先・ソースの実在や種類を自動確認していません。対象不明ならOBSで確認し、無関係なソースを変更しないでください。",
    "guide.copy.156": "声と伴奏を含むソース名を入力してください。",
    "guide.copy.157": "マイクと伴奏を識別できる異なる名前を入力してください。混合済みの1ソースなら取り込み方を選び直してください。",
    "guide.copy.158": "2. 経路・録音対象を確認する",
    "guide.copy.159": "3. OBSで短く録画し、聴く",
    "guide.copy.160": "普段使うアプリで伴奏を流し、普段の声とサビ程度の声で短く歌います。",
    "guide.copy.161": "OBSで利用者自身が録画を開始・停止し、保存された動画を再生します。録画・配信中なら、先に試験を行える状態へ戻してください。",
    "guide.copy.162": "声が伴奏に埋もれないか、声だけ大きすぎないか、二重に聞こえないかを確認します。数値差だけで合否を決めません。",
    "guide.copy.163": "この案内は録画の開始・停止、設定変更、ファイルの保存・削除や外部送信を行いません。試験後のファイルは保存先を確認してOBS側で管理してください。",
    "guide.copy.164": "最終録画を聴いた結果",
    "guide.copy.165": "まだ確認していません",
    "guide.copy.166": "声と伴奏の両方を聴き取れました",
    "guide.copy.167": "声が伴奏に埋もれます",
    "guide.copy.168": "声だけ大きく感じます",
    "guide.copy.169": "二重に聞こえます",
    "guide.copy.170": "判断できません",
    "guide.copy.171": "今回の確認を記録",
    "guide.copy.172": "判断できないため未確認です。対象や録音トラックを確認し、設定を変えずに再確認してください。",
    "guide.copy.173": "この画面内に自己確認を記録しました。自動測定や品質の合格判定ではありません。",
    "guide.copy.174": "音量を変える場合は変更前の値を控え、利用者自身が少しずつ調整→再録画→聴いて採用または元の値へ戻してください。Auralynの設定変更は既存の設定画面で、OBS連携の変更は既存の変更予定・履歴で対象と差分を確認してください。",
    "guide.copy.175": "ソースの改名・削除、OBSの再接続・シーンコレクション変更、音声経路や処理の変更後は確認をやり直してください。このメモは画面を閉じると消えます。",
    "guide.copy.176": "対象と確認をやり直す",
    "guide.copy.177": "録画を基にしたタイミング調整は、以下の専用操作から対象と差分を確認して行えます。Auralyn内部の遅延をそのままOBSの同期オフセットへ転記しないでください。歌うときに自分の声が遅れて聞こえる問題は、最終録画内の声と伴奏の同期とは別です。映像との同期には別の確認基準が必要です。",
    "guide.copy.178": "タイミング調整を閉じる",
    "guide.copy.179": "録画のタイミング調整を開く",
    "guide.copy.180": "現在の音声設定を取得できませんでした。テストと保存は実行できません。ウィザードを開き直してください。",
    "guide.copy.181": "入力と出力を自分で選びます。",
