    "guide.copy.282": "自動確認には OBS WebSocket v5 が必要です。OBS の「ツール → WebSocketサーバー設定」で有効にしてください。利用できない場合は、「マイクの音を流して確認」を押してマイクに話し、OBS の該当ソースのメーターが動くか手動で確認してください。",
