    "guide.copy.289": "設定画面に保存したホスト名・ポートを初期表示します。ここでの変更は一時的で、保存済み設定は変更しません。「OBS に接続する」を押すと、既存のOBS接続もこの接続先へ切り替わります。 パスワードはこの画面から保存しません。他にOBSを使う画面がなければ、ウィザードを閉じると接続を終了します。再利用するときは接続してください。",
