    "templates.chatting.name": "Just Chatting",
    "templates.chatting.description": "A basic chain for reducing steady noise and evening out voice levels with compression.",
    "templates.chatting.slot0.label": "Noise gate",
    "templates.chatting.slot0.notes": "Reduces steady noise such as PC fans while you are not speaking. Adjust Threshold so it acts during pauses.",
    "templates.chatting.slot1.label": "Compressor",
    "templates.chatting.slot1.notes": "Reduces differences between quiet and loud speech. A starting example is Ratio 4:1 and about 3–6 dB of gain reduction.",
    "templates.chatting.slot2.label": "Limiter",
    "templates.chatting.slot2.notes": "An example for controlling loud peaks. Place it last and try a ceiling around −1.0 dB.",
    "templates.singing.name": "Singing",
    "templates.singing.description": "An example singing chain with EQ, compression, reverb and a limiter.",
    "templates.singing.slot0.label": "Equalizer (EQ)",
    "templates.singing.slot0.notes": "A starting example is cutting below 100 Hz and slightly raising 2–4 kHz to bring the voice forward.",
    "templates.singing.slot1.label": "Compressor",
    "templates.singing.slot1.notes": "Evens out singing dynamics. Compare settings by listening; singing may use stronger compression than speech.",
    "templates.singing.slot2.label": "Reverb",
    "templates.singing.slot2.notes": "Adds a sense of space. Start with a restrained Mix of about 10–20%.",
    "templates.singing.slot3.label": "Limiter",
    "templates.singing.slot3.notes": "Adjust the ceiling and input level to control peaks. This does not guarantee that clipping is prevented.",
    "templates.ASMR.name": "ASMR",
    "templates.ASMR.description": "An ASMR chain example with compression and limiting. It does not guarantee level limits or hearing protection.",
    "templates.ASMR.slot0.label": "Compressor (gentle)",
    "templates.ASMR.slot0.notes": "Used to raise quiet sounds. A longer release is a starting point.",
    "templates.ASMR.slot1.label": "Limiter (level control)",
    "templates.ASMR.slot1.notes": "Check the ceiling and input level, then listen from a low playback level. This does not guarantee device volume or hearing safety.",
