    "guide.copy.131": "Input sensitivity",
    "guide.copy.132": "If speech cuts out, compare automatic detection and sensitivity. Choose a setting that responds to your usual voice without triggering on breathing or background sound alone.",
    "guide.copy.133": "These are instructions only. Audio arrival at the receiving app is unconfirmed. Check its meter and listen there.",
    "guide.copy.134": "Open connection diagnostics",
    "guide.copy.135": "Listen in Voice Check",
    "guide.copy.136": "Go back one step",
    "guide.copy.137": "Back",
