    "guide.copy.141": "Close guide",
    "guide.copy.142": "I checked the voice and backing-track sources in OBS for duplicate capture through desktop audio or another microphone",
    "guide.copy.143": "I checked mute and audio monitoring for the sources, including possible recapture of monitor audio",
    "guide.copy.144": "I checked recording tracks, destination and included audio, and made sure test audio will not reach a broadcast or call",
    "guide.copy.145": "Check the final OBS mix (manual)",
    "guide.copy.146": "Voice Check alone, or a connection test that detects a tone in OBS, does not confirm the voice/backing-track balance or the final recording.",
    "guide.copy.147": "1. Identify the sources in OBS",
    "guide.copy.148": "How audio enters OBS",
    "guide.copy.149": "Voice and backing track use separate sources",
    "guide.copy.150": "Voice and backing track are mixed in one source",
    "guide.copy.151": "Name of the mixed source",
    "guide.copy.152": "Microphone source name",
    "guide.copy.153": "Backing-track source name",
    "guide.copy.154": "Hardware loopback may already mix both into one OBS source. Adjust their individual levels in the upstream mixer or player. A premixed source is different from capturing the same audio twice through separate routes.",
    "guide.copy.155": "Names are manual notes. This does not verify the OBS connection or whether a source exists or is of the expected type. Check in OBS if unsure; do not change unrelated sources.",
    "guide.copy.156": "Enter the source name containing voice and backing track.",
    "guide.copy.157": "Enter different names that identify the microphone and backing track. If they are already mixed in one source, change the routing choice above.",
    "guide.copy.158": "2. Check routing and recording targets",
    "guide.copy.159": "3. Make a short OBS recording and listen",
    "guide.copy.160": "Play your usual backing track, then sing briefly at your usual level and at a louder chorus level.",
    "guide.copy.161": "Start and stop recording yourself in OBS, then play the saved video. If broadcasting or recording, first return to a state where a test is safe.",
    "guide.copy.162": "Listen for a buried or overly loud voice, and for doubled audio. Do not judge the result from numerical differences alone.",
    "guide.copy.163": "These instructions do not start/stop recording, change settings, save/delete files or send anything externally. Manage test files yourself after checking OBS’s recording destination.",
    "guide.copy.164": "What you heard in the final recording",
    "guide.copy.165": "Not checked yet",
    "guide.copy.166": "Both voice and backing track were audible",
    "guide.copy.167": "Voice is buried in the backing track",
    "guide.copy.168": "Voice sounds too loud",
    "guide.copy.169": "Audio sounds doubled",
    "guide.copy.170": "I cannot judge",
    "guide.copy.171": "Note this check",
    "guide.copy.172": "Unconfirmed because you could not judge. Check the sources and recording tracks, then check again without changing settings.",
    "guide.copy.173": "Your self-check is noted in this screen only. This is not an automated measurement or a quality pass.",
    "guide.copy.174": "Before adjusting levels, note the original values. Make small changes yourself, record again, then listen and accept or undo them. Use existing Auralyn settings, or OBS change previews/history, to check targets and differences.",
    "guide.copy.175": "Check again after renaming/deleting sources, reconnecting OBS, changing scene collections, or changing audio routing/processing. This note disappears when the screen closes.",
    "guide.copy.176": "Reset sources and checks",
    "guide.copy.177": "Use the dedicated operation below to review recording timing targets and differences. Do not copy Auralyn’s internal latency into an OBS sync offset. Delayed self-monitoring while singing is separate from voice/backing-track timing in the final recording. Audio/video sync requires a separate reference.",
    "guide.copy.178": "Close timing adjustment",
    "guide.copy.179": "Open recording timing adjustment",
