export function message(locale: Locale, key: MessageKey, args?: Record<string, string | number>): string { return (locale === 'en' ? en : ja)[key].replace(/\{(\w+)\}/g, (token, name: string) => args?.[name] === undefined ? token : String(args[name])); }
